gcode_macro _check_z_hit.gcode:
{% set Z_POSITION = printer.toolhead.position.z | default(0) | float | round(3) %}
{% set Z_PROBE_OFFSET = printer.configfile.settings.probe.z_offset | default(0) | float | round(3) %}
{% set Z_PRINTBED_OFFSET = printer.save_variables.variables.z_printbed_offset | default(0.4) | float | round(3) %}

{% if printer['gcode_button pa0'].state == "PRESSED" %}
RESPOND TYPE=command MSG="Z-end button hit at {Z_POSITION}"
SAVE_VARIABLE VARIABLE=z_endstop_hit VALUE={Z_POSITION}
{% set CALCULATED_Z_PROBE_OFFSET = Z_PROBE_OFFSET + Z_POSITION * -1 - Z_PRINTBED_OFFSET %}
SAVE_VARIABLE VARIABLE=z_calculate_probe VALUE={CALCULATED_Z_PROBE_OFFSET}
RESPOND TYPE=command MSG="Manually modify the probe z-offset in the printer.cfg to {CALCULATED_Z_PROBE_OFFSET}"
{% endif %}

gcode_macro _ensure_homed.gcode:
{% if "xyz" not in printer.toolhead.homed_axes %}
G28
{% endif %}

gcode_macro _extrude.gcode:
{% set length = params.LENGTH|default(0)|float %}
{% set speed = params.SPEED|default(35)|float %}
{% if length != 0 %}
{% if printer.extruder.can_extrude %}
SAVE_GCODE_STATE NAME=_extrude
M83
G1 E{length} F{speed * 60}
RESTORE_GCODE_STATE NAME=_extrude
{% else %}
RESPOND MSG="Nozzle too cold - skipped extruding {length}mm"
{% endif %}
{% endif %}

gcode_macro _goto_tower.gcode:
{% set s = printer['gcode_macro _PRINTER_SETTINGS'] %}
{% set pos = printer.gcode_move.gcode_position %}
SAVE_GCODE_STATE NAME=_tower
G90
{% if pos.z < s.tower_z %}
G1 Z{s.tower_z} F{s.z_speed * 60}
{% endif %}
G1 X{s.tower_x} Y{s.tower_y} F{s.travel_speed * 60}
G1 Z{s.tower_z} F{s.z_speed * 60}
M400
RESTORE_GCODE_STATE NAME=_tower

gcode_macro _heat_for_filament.gcode:
{% set s = printer['gcode_macro _PRINTER_SETTINGS'] %}
{% set p = printer['gcode_macro PAUSE'] %}
{% set min_temp = printer.configfile.settings.extruder.min_extrude_temp %}
{% set temp = params.TEMP|default(0)|float %}
{% if temp == 0 %}
{% if printer.pause_resume.is_paused and p.extruder_temp >= min_temp %}
{% set temp = p.extruder_temp %}
{% elif printer.extruder.target >= min_temp %}
{% set temp = printer.extruder.target %}
{% else %}
{% set temp = s.filament_temp %}
{% endif %}
{% endif %}
RESPOND MSG="Heating nozzle to {temp|int}C"
M109 S{temp}

gcode_macro _move_z_down.gcode:
{% if printer.save_variables.variables.z_endstop_hit == 0 %}
G1 Z-0.01 F50
M400
_CHECK_Z_HIT
{% endif %}

gcode_macro _park.gcode:
{% set s = printer['gcode_macro _PRINTER_SETTINGS'] %}
{% if "xyz" not in printer.toolhead.homed_axes %}
RESPOND MSG="Not homed - skipping park move"
{% else %}
{% set origin = printer.gcode_move.homing_origin %}
{% set pos = printer.gcode_move.gcode_position %}
{% set amin = printer.toolhead.axis_minimum %}
{% set amax = printer.toolhead.axis_maximum %}
{% set lift = params.LIFT|default(s.park_lift)|float %}
{% set z_min = params.Z_MIN|default(0)|float %}
{% set z = [[pos.z + lift, z_min]|max, amax.z - origin.z - 2]|min %}
{% set x = [[params.X|default(s.park_x)|float, amin.x - origin.x]|max, amax.x - origin.x]|min %}
{% set y = [[params.Y|default(s.park_y)|float, amin.y - origin.y]|max, amax.y - origin.y]|min %}
SAVE_GCODE_STATE NAME=_park
G90
{% if z > pos.z %}
G1 Z{z} F{s.z_speed * 60}
{% endif %}
{% if params.XY|default(1)|int %}
G1 X{x} Y{y} F{s.travel_speed * 60}
{% endif %}
RESTORE_GCODE_STATE NAME=_park
{% endif %}

gcode_macro _wipe.gcode:
{% set s = printer['gcode_macro _PRINTER_SETTINGS'] %}
{% set pos = printer.gcode_move.gcode_position %}
SAVE_GCODE_STATE NAME=_wipe
G90
{% if pos.z < 5 %}
G1 Z5 F{s.z_speed * 60}
{% endif %}
G1 X{s.wipe_x_start} Y{s.wipe_y} F{s.travel_speed * 60}
G1 Z0 F{s.z_speed * 60}
{% for i in range(s.wipe_passes|int) %}
G1 X{s.wipe_x_end} F6000
G1 X{s.wipe_x_start} F6000
{% endfor %}
G1 Z5 F{s.z_speed * 60}
RESTORE_GCODE_STATE NAME=_wipe

gcode_macro cancel_print.gcode:
{% set s = printer['gcode_macro _PRINTER_SETTINGS'] %}
{% if cancelled and not printer.pause_resume.is_paused %}
RESPOND MSG="Cancel already done"
{% else %}
SET_GCODE_VARIABLE MACRO=CANCEL_PRINT VARIABLE=cancelled VALUE=True
UPDATE_DELAYED_GCODE ID=_RESET_CANCEL DURATION=30
_EXTRUDE LENGTH=-{s.cancel_retract} SPEED={s.retract_speed}
TURN_OFF_HEATERS
M106 S0
{% if not printer.pause_resume.is_paused %}
_PARK X={s.end_park_x} Y={s.end_park_y} LIFT={s.end_lift}
{% endif %}
SET_PAUSE_NEXT_LAYER ENABLE=0
SET_PAUSE_AT_LAYER ENABLE=0 LAYER=0
SET_GCODE_VARIABLE MACRO=PAUSE VARIABLE=m600 VALUE=False
SET_GCODE_VARIABLE MACRO=PAUSE VARIABLE=reason VALUE="'none'"
BED_MESH_CLEAR
_RESTORE_IDLE_TIMEOUT
CANCEL_PRINT_BASE
RESPOND MSG="Print cancelled"
{% endif %}

gcode_macro clean_nozzle.gcode:
{% set temp = params.TEMP|default(220)|float %}
{% if printer.pause_resume.is_paused %}
RESPOND TYPE=error MSG="CLEAN_NOZZLE is not allowed while paused (it re-homes)"
{% else %}
_ENSURE_HOMED
G90
G1 Z10 F{8 * 60}
M109 S{temp}
_WIPE
G90
G1 Z0 F{8 * 60}
M106 S255
G1 X80 F6000
M109 S150
M106 S0
M104 S0
G1 Z10 F{8 * 60}
G28
{% endif %}

gcode_macro dry_filament.gcode:
{% set temp = params.TEMP|default(60)|float %}
{% set hours = params.HOURS|default(3)|float %}
M140 S{temp}
SET_IDLE_TIMEOUT TIMEOUT={(hours * 3600 + 600)|int}
UPDATE_DELAYED_GCODE ID=_DRY_FILAMENT_DONE DURATION={(hours * 3600)|int}
RESPOND MSG="Drying at {temp|int}C for {hours} h. STOP_DRYING to end early."

gcode_macro load_filament.gcode:
{% set s = printer['gcode_macro _PRINTER_SETTINGS'] %}
{% set length = params.LENGTH|default(s.load_length)|float %}
{% set purge = params.PURGE|default(s.load_purge)|float %}
{% if printer.pause_resume.is_paused %}
_HEAT_FOR_FILAMENT TEMP={params.TEMP|default(0)}
_FILAMENT_MOVE E={length + purge} SPEED={s.load_speed}
_FILAMENT_MOVE E=-1 SPEED=30

SET_GCODE_VARIABLE MACRO=PAUSE VARIABLE=m600 VALUE=False
RESPOND MSG="Filament loaded at the park spot - RESUME when ready"
{% else %}
_ENSURE_HOMED
_GOTO_TOWER
_HEAT_FOR_FILAMENT TEMP={params.TEMP|default(0)}
_FILAMENT_MOVE E={length + purge} SPEED={s.load_speed}
_FILAMENT_MOVE E=-1 SPEED=30
G4 P1500
_WIPE
RESPOND MSG="Filament loaded, purged on the tower and nozzle wiped"
{% endif %}

gcode_macro m600.gcode:
{% set s = printer['gcode_macro _PRINTER_SETTINGS'] %}
{% if printer.pause_resume.is_paused %}
RESPOND MSG="Already paused"
{% else %}
SET_GCODE_VARIABLE MACRO=PAUSE VARIABLE=m600 VALUE=True
PAUSE Z_MIN={s.m600_z_min} REASON=m600
{% if s.m600_unload %}
UNLOAD_FILAMENT
{% endif %}
RESPOND MSG="Filament change: UNLOAD_FILAMENT, insert new filament, LOAD_FILAMENT, then RESUME"
{% endif %}

gcode_macro mesh_calibrate.gcode:
{% set BED_TEMP = params.BED_TEMP|default(60)|float %}
M104 S0
M190 S{BED_TEMP}
G28
BED_MESH_CALIBRATE
SAVE_VARIABLE VARIABLE=mesh_bed_temp VALUE={BED_TEMP}
RESPOND PREFIX="info" MSG="Bed mesh done - saving (Klipper will restart)"
SAVE_CONFIG

gcode_macro pause.gcode:
{% set s = printer['gcode_macro _PRINTER_SETTINGS'] %}
{% if printer.pause_resume.is_paused %}
RESPOND MSG="Already paused"
{% else %}
{% set x = params.X|default(s.park_x) %}
{% set y = params.Y|default(s.park_y) %}
{% set z_min = params.Z_MIN|default(0) %}
{% set park_xy = params.PARK|default(1)|int %}
{% set reason = params.REASON|default('layer' if layer_trigger else 'manual')|lower %}
SET_GCODE_VARIABLE MACRO=PAUSE VARIABLE=reason VALUE="'{reason}'"
SET_GCODE_VARIABLE MACRO=PAUSE VARIABLE=layer_trigger VALUE=False
SET_GCODE_VARIABLE MACRO=PAUSE VARIABLE=extruder_temp VALUE={printer.extruder.target}
SET_IDLE_TIMEOUT TIMEOUT={s.pause_idle_timeout}
PAUSE_BASE
_EXTRUDE LENGTH=-{s.pause_retract} SPEED={s.retract_speed}
_PARK X={x} Y={y} LIFT={s.park_lift} Z_MIN={z_min} XY={park_xy}
RESPOND MSG="Paused. Nozzle held at {printer.extruder.target|int}C for {(s.pause_idle_timeout / 60)|int} min."
{% endif %}

gcode_macro preheat.gcode:
{% set presets = {'PLA': [210, 60], 'PETG': [240, 75], 'ABS': [250, 100], 'TPU': [225, 50]} %}
{% set m = params.MATERIAL|default('PLA')|upper %}
{% if m in presets %}
M104 S{presets[m][0]}
M140 S{presets[m][1]}
RESPOND MSG="Preheating for {m}: nozzle {presets[m][0]}C, bed {presets[m][1]}C"
{% else %}
RESPOND TYPE=error MSG="Unknown material {m} (use PLA, PETG, ABS or TPU)"
{% endif %}

gcode_macro purge_filament.gcode:
{% set s = printer['gcode_macro _PRINTER_SETTINGS'] %}
{% set length = params.LENGTH|default(s.load_purge)|float %}
{% if printer.pause_resume.is_paused %}
_HEAT_FOR_FILAMENT TEMP={params.TEMP|default(0)}
_FILAMENT_MOVE E={length} SPEED=5
_FILAMENT_MOVE E=-1 SPEED=30
{% else %}
_ENSURE_HOMED
_GOTO_TOWER
_HEAT_FOR_FILAMENT TEMP={params.TEMP|default(0)}
_FILAMENT_MOVE E={length} SPEED=5
_FILAMENT_MOVE E=-1 SPEED=30
G4 P1500
_WIPE
{% endif %}
RESPOND MSG="Purged {length|int} mm"

gcode_macro resume.gcode:
{% set s = printer['gcode_macro _PRINTER_SETTINGS'] %}
{% set p = printer['gcode_macro PAUSE'] %}
{% set velocity = params.VELOCITY|default(printer.configfile.settings.pause_resume.recover_velocity) %}
{% set keep_offsets = params.KEEP_OFFSETS|default(0)|int %}
{% set origin = printer.gcode_move.homing_origin %}
{% if not printer.pause_resume.is_paused %}
RESPOND MSG="Not paused - nothing to resume"
{% elif "xyz" not in printer.toolhead.homed_axes %}
RESPOND TYPE=error MSG="Axes are no longer homed (motors were switched off) - this print cannot be resumed safely. Use CANCEL_PRINT."
{% else %}
{% if p.extruder_temp > 0 %}
{% if printer.extruder.target < p.extruder_temp %}
RESPOND MSG="Reheating nozzle to {p.extruder_temp|int}C"
{% endif %}
M109 S{p.extruder_temp}
{% endif %}
{% if p.m600 %}
_EXTRUDE LENGTH={s.m600_purge} SPEED=5
G4 P1000
{% endif %}
_EXTRUDE LENGTH={s.resume_prime} SPEED={s.retract_speed}
SET_GCODE_VARIABLE MACRO=PAUSE VARIABLE=m600 VALUE=False
SET_GCODE_VARIABLE MACRO=PAUSE VARIABLE=reason VALUE="'none'"
_RESTORE_IDLE_TIMEOUT
RESUME_BASE VELOCITY={velocity}
{% if keep_offsets %}

SET_GCODE_OFFSET X={origin.x} Y={origin.y} Z={origin.z} MOVE=1
{% endif %}
{% endif %}

gcode_macro set_pause_at_layer.gcode:
{% set pause_at_layer = printer['gcode_macro SET_PRINT_STATS_INFO'].pause_at_layer %}
{% set ENABLE = params.ENABLE | int != 0 if params.ENABLE is defined
else params.LAYER is defined %}
{% set LAYER = params.LAYER | default(pause_at_layer.layer) | int %}
{% set MACRO = params.MACRO | default(pause_at_layer.call, True) %}
SET_GCODE_VARIABLE MACRO=SET_PRINT_STATS_INFO VARIABLE=pause_at_layer VALUE="{{ 'enable': ENABLE, 'layer': LAYER, 'call': MACRO }}"

gcode_macro set_pause_next_layer.gcode:
{% set pause_next_layer = printer['gcode_macro SET_PRINT_STATS_INFO'].pause_next_layer %}
{% set ENABLE = params.ENABLE | default(1)|int != 0 %}
{% set MACRO = params.MACRO | default(pause_next_layer.call, True) %}
SET_GCODE_VARIABLE MACRO=SET_PRINT_STATS_INFO VARIABLE=pause_next_layer VALUE="{{ 'enable': ENABLE, 'call': MACRO }}"

gcode_macro set_print_stats_info.gcode:
SET_PRINT_STATS_INFO_BASE {rawparams}
{% if pause_next_layer.enable and params.CURRENT_LAYER is defined %}
RESPOND TYPE=echo MSG='{"%s, forced by pause_next_layer" % pause_next_layer.call}'
SET_GCODE_VARIABLE MACRO=PAUSE VARIABLE=layer_trigger VALUE=True
{pause_next_layer.call}
SET_PAUSE_NEXT_LAYER ENABLE=0
{% elif pause_at_layer.enable and params.CURRENT_LAYER is defined and params.CURRENT_LAYER | int == pause_at_layer.layer %}
RESPOND TYPE=echo MSG='{"%s, forced by pause_at_layer [%d]" % (pause_at_layer.call, pause_at_layer.layer)}'
SET_GCODE_VARIABLE MACRO=PAUSE VARIABLE=layer_trigger VALUE=True
{pause_at_layer.call}
SET_PAUSE_AT_LAYER ENABLE=0
{% endif %}

gcode_macro start_print.gcode:
{% set s = printer['gcode_macro _PRINTER_SETTINGS'] %}
{% set BED_TEMP = params.BED_TEMP|default(60)|float %}
{% set EXTRUDER_TEMP = params.EXTRUDER_TEMP|default(200)|float %}
{% set MESH = params.MESH|default(s.start_mesh)|lower %}
{% set PROBE_TEMP = [s.probe_nozzle_temp, EXTRUDER_TEMP]|min %}

CLEAR_PAUSE
SET_GCODE_VARIABLE MACRO=CANCEL_PRINT VARIABLE=cancelled VALUE=False
SET_GCODE_VARIABLE MACRO=PAUSE VARIABLE=m600 VALUE=False
SET_GCODE_VARIABLE MACRO=PAUSE VARIABLE=reason VALUE="'none'"
BED_MESH_CLEAR


M140 S{BED_TEMP}
M104 S{PROBE_TEMP}
M190 S{BED_TEMP}

G90
G28

{% if MESH == 'adaptive' %}
BED_MESH_CALIBRATE ADAPTIVE=1
{% elif MESH == 'saved' %}
BED_MESH_PROFILE LOAD="default"
{% endif %}


G1 X50 Y0 Z3 F{s.travel_speed * 60}
M109 S{EXTRUDER_TEMP}
_PURGE_LINE

gcode_macro unload_filament.gcode:
{% set s = printer['gcode_macro _PRINTER_SETTINGS'] %}
{% set length = params.LENGTH|default(s.unload_length)|float %}
{% if not printer.pause_resume.is_paused %}
_ENSURE_HOMED
_GOTO_TOWER
{% endif %}
_HEAT_FOR_FILAMENT TEMP={params.TEMP|default(0)}
_FILAMENT_MOVE E=10 SPEED=5
_FILAMENT_MOVE E=-15 SPEED=50
G4 P2000
_FILAMENT_MOVE E=-{length - 15} SPEED={s.unload_speed}
RESPOND MSG="Filament unloaded"

gcode_macro z_endstop_hit.gcode:
{% set Z_ENDSTOP_HIT = printer.save_variables.variables.z_endstop_hit | default(0) | float | round(3) %}
RESPOND TYPE=command MSG="Reset z_endstop_hit from {Z_ENDSTOP_HIT} to 0.0"
SAVE_VARIABLE VARIABLE=z_endstop_hit VALUE=0
G90
G1 X58.10 Y238.80 Z5 F8000

M400
G1 X58.10 Y238.80 Z3 F500
M400
G91
{% set z_count = 500 %}
{% for cz in range(z_count) %}
_MOVE_Z_DOWN
{% endfor %}

idle_timeout.gcode:
{% if printer.pause_resume.is_paused %}
M104 S0
RESPOND TYPE=error MSG="Paused too long: hotend switched off, bed and motors kept on. RESUME will reheat."
{% else %}
TURN_OFF_HEATERS
M84
{% endif %}
